Ladies and gentlemen, our test planning begins with a joke: A developer, a QA engineer, and a product manager walk into a checkout flow. Only the tests made it out alive.

```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock context providers - the bureaucracy says we need these
const mockCart = {
  items: [{ id: '1', name: 'Martini Glass', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn(),
};
const mockPayment = { processPayment: vi.fn() };

vi.mock('./CartContext', () => ({ useCart: () => mockCart }));
vi.mock('./PaymentContext', () => ({ usePayment: () => mockPayment }));

const validShipping = {
  street: '4077 MASH Lane',
  city: 'Uijeongbu',
  state: 'CA',
  zip: '90210',
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'Benjamin Franklin Pierce',
};

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockCart.items = [{ id: '1', name: 'Martini Glass', price: 29.99 }];
  });

  // Happy path - because sometimes miracles happen
  it('completes full checkout flow successfully', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    mockPayment.processPayment.mockResolvedValue({ orderId: 'ORD-4077' });

    render(<Checkout onComplete={onComplete} />);

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), validShipping.street);
    await user.type(screen.getByLabelText(/city/i), validShipping.city);
    await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
    await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
    await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
    await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
    await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review & submit
    expect(screen.getByText(/martini glass/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-4077');
  });

  // Validation - the bureaucracy says no, I say validate
  describe('shipping validation', () => {
    it('displays error for empty street address', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // Edge cases - unfortunately, we're all in this together
  it('shows empty cart message when cart has no items', () => {
    mockCart.items = [];
    render(<Checkout onCancel={vi.fn()} />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
  });

  it('handles payment failure gracefully', async () => {
    const user = userEvent.setup();
    mockPayment.processPayment.mockRejectedValue(new Error('Card declined'));
    render(<Checkout />);

    // Navigate to review step... (abbreviated)
    // Then place order
    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
  });

  // Accessibility - no soldier left behind
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it('shows loading state during submission', async () => {
    mockPayment.processPayment.mockImplementation(() => new Promise(() => {}));
    // ... navigate to review, click place order
    expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
  });
});
